use fugue::{git::{Git,Entry},journal,merge,round,util,view::View};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,path::Path,process::Command};
fn fixture()->(tempfile::TempDir,Git,String){let d=tempfile::tempdir().unwrap();assert!(Command::new("git").args(["init","-q","--initial-branch=main"]).arg(d.path()).status().unwrap().success());let g=Git::open(d.path()).unwrap();let mut m=BTreeMap::new();m.insert("tracked".into(),Entry{kind:"file".into(),mode:0o100644,id:g.put_blob(b"base tracked\n").unwrap()});let base=g.commit_tree(&g.put_tree(&m).unwrap(),&[],"base").unwrap();g.advance("refs/heads/main",&base,None).unwrap();util::replace_leaf(&d.path().join("tracked"),Some(&util::Leaf{mode:0o100644,bytes:b"base tracked\n".to_vec()})).unwrap();assert!(Command::new("git").arg("-C").arg(d.path()).args(["add","tracked"]).status().unwrap().success());util::atomic_write(&d.path().join(".fugue/config"),serde_json::to_vec(&json!({"round":{"id":"r1"},"actions":{"check":{"argv":["/usr/bin/true"]}}})).unwrap().as_slice()).unwrap();(d,g,base)}
fn split(n:usize)->Value{json!((0..n).map(|i|json!({"goal":format!("write result {i}"),"ownedPaths":[format!("result{i}")],"deliverables":[{"path":format!("result{i}"),"form":"file"}],"assertions":[{"name":format!("check{i}"),"action":"check","expect":0}]})).collect::<Vec<_>>())}
fn rows(r:&Path)->Vec<Value>{journal::read(r,"round").unwrap().into_iter().map(|x|x.event).collect()}
fn refs(g:&Git)->Vec<u8>{g.run(&["for-each-ref","--format=%(refname) %(objectname)"],None).unwrap()}
fn issued(c:&Value)->Value{json!({"t":"contract/issue","round":"r1","contract":c["id"],"owner":c["agent"],"paths":c["ownedPaths"],"body":serde_json::to_string(c).unwrap()})}
fn state(r:&Path,from:&str,to:&str){journal::append(r,"round",json!({"t":"round/state","round":"r1","from":from,"to":to})).unwrap();}
fn target(g:&Git,base:&str)->(String,Entry,Entry){let mut m=g.tree(base).unwrap();let old=m["tracked"].clone();let new=Entry{kind:"file".into(),mode:0o100755,id:g.put_blob(b"new tracked\n").unwrap()};m.insert("tracked".into(),new.clone());let c=g.commit_tree(&g.put_tree(&m).unwrap(),&[base.into()],"target").unwrap();(c,old,new)}
fn begin(base:&str,c:&str,old:&Entry,new:&Entry)->Value{json!({"t":"advance/begin","tx":"tx1","round":"r1","ref":"refs/heads/main","base":base,"commit":c,"changes":[{"path":"tracked","old":old,"new":new}]})}
#[test]fn partial_approved_issue_recovers_then_duplicate_go_changes_nothing(){let(d,g,base)=fixture();let p=round::command(d.path(),"plan",&["goal".into()],&json!({"split":split(2)})).unwrap();let cs=p["contracts"].as_array().unwrap();for c in cs{g.advance(c["branch"].as_str().unwrap(),&base,None).unwrap();}let fp=format!("{:x}",Sha256::digest(util::canonical(&json!(cs)).unwrap()))[..16].to_owned();journal::append(d.path(),"round",json!({"t":"round/approve","round":"r1","fingerprint":fp,"contracts":cs.iter().map(|x|x["id"].clone()).collect::<Vec<_>>()})).unwrap();journal::append(d.path(),"round",issued(&cs[0])).unwrap();let index=fs::read(d.path().join(".git/index")).unwrap();let z=round::command(d.path(),"go",&[],&json!({})).unwrap();assert_eq!(z["state"],"Working");assert_eq!(z["recovered"],true);let rs=rows(d.path());assert_eq!(rs.iter().filter(|x|x["t"]=="contract/issue").count(),2);assert_eq!(rs.iter().filter(|x|x["t"]=="round/approve").count(),1);let log=fs::read(d.path().join(".fugue/log/round.jsonl")).unwrap();let rf=refs(&g);assert!(round::command(d.path(),"go",&[],&json!({})).is_err());assert_eq!(fs::read(d.path().join(".fugue/log/round.jsonl")).unwrap(),log);assert_eq!(refs(&g),rf);assert_eq!(fs::read(d.path().join(".git/index")).unwrap(),index);assert_eq!(g.resolve("refs/heads/main").unwrap().as_deref(),Some(base.as_str()));}
#[test]fn delegated_dispatch_restart_does_not_reissue_contracts(){let(d,g,base)=fixture();let p=round::command(d.path(),"plan",&["goal".into()],&json!({"split":split(1)})).unwrap();let c=p["contracts"][0].clone();g.advance(c["branch"].as_str().unwrap(),&base,None).unwrap();journal::append(d.path(),"round",issued(&c)).unwrap();state(d.path(),"Planning","Delegated");let z=round::command(d.path(),"go",&[],&json!({})).unwrap();assert_eq!(z["state"],"Working");assert_eq!(rows(d.path()).iter().filter(|x|x["t"]=="contract/issue").count(),1);}
#[test]fn collecting_merging_and_verifying_resume_reuse_workers_and_preserve_host_on_failed_assertion(){for stage in ["Collecting","Merging","Verifying"]{let(d,g,base)=fixture();let p=round::command(d.path(),"new",&["goal".into()],&json!({"split":split(1)})).unwrap();let c=&p["contracts"][0];let w=c["agent"].as_str().unwrap();let mut v=View::load(d.path(),w,None).unwrap();v.write("result0",b"completed worker\n",None).unwrap();let ck=v.checkpoint("worker complete").unwrap();journal::append(d.path(),w,json!({"t":"agent/stop","agent":w,"contract":c["id"],"reason":"end-turn","stopped":"done","steps":0})).unwrap();let before=fs::read(d.path().join(format!(".fugue/log/{w}.jsonl"))).unwrap();state(d.path(),"Working","Collecting");if stage!="Collecting"{state(d.path(),"Collecting","Merging");}if stage=="Verifying"{let f=merge::fold(&g,&base,&[ck["commit"].as_str().unwrap().into()]).unwrap();let tree=f["tree"].as_str().unwrap();let candidate=g.commit_tree(tree,&[base.clone()],"fugue round r1").unwrap();journal::append(d.path(),"round",json!({"t":"merge/candidate","round":"r1","base":base,"tree":tree,"commit":candidate})).unwrap();state(d.path(),"Merging","Verifying");}let index=fs::read(d.path().join(".git/index")).unwrap();let z=round::command(d.path(),"work",&[],&json!({"fail":"check0","retry":0})).unwrap();assert_eq!(z["state"],"Aborted","stage {stage}: {z}");assert_eq!(z["ok"],false);assert_eq!(z["verify"]["fail"],1);assert_eq!(z["reused"].as_array().unwrap().len(),1);assert_eq!(g.resolve("refs/heads/main").unwrap().as_deref(),Some(base.as_str()));assert_eq!(fs::read(d.path().join("tracked")).unwrap(),b"base tracked\n");assert!(!d.path().join("result0").exists());assert_eq!(fs::read(d.path().join(".git/index")).unwrap(),index);assert_eq!(fs::read(d.path().join(format!(".fugue/log/{w}.jsonl"))).unwrap(),before);assert!(!rows(d.path()).iter().any(|x|x["t"]=="advance/begin"||x["t"]=="merge/accept"));}}
#[test]fn native_unrunnable_or_successful_verification_reports_actual_result(){let(d,g,base)=fixture();let z=round::command(d.path(),"run",&["goal".into()],&json!({"split":split(1)})).unwrap();let pass=z["verify"]["pass"].as_u64().unwrap();let un=z["verify"]["unrunnable"].as_u64().unwrap();let fail=z["verify"]["fail"].as_u64().unwrap();assert_eq!(pass+un+fail,1,"unexpected verification: {z}");if pass==0{assert_eq!(z["ok"],false);assert_eq!(z["state"],"Aborted");assert_eq!(g.resolve("refs/heads/main").unwrap().as_deref(),Some(base.as_str()));assert!(!d.path().join("result0").exists());assert_eq!(fs::read(d.path().join("tracked")).unwrap(),b"base tracked\n");}else{assert_eq!(z["ok"],true);assert_eq!(z["state"],"Rebuilding");assert!(d.path().join("result0").is_file());}}
#[test]fn malformed_wal_target_old_ref_duplicate_and_ids_are_rejected_without_mutation(){for case in ["target-tree","target-blob","old","ref","duplicate","id","duplicate-begin"]{let(d,g,base)=fixture();let(c,old,new)=target(&g,&base);let mut wal=begin(&base,&c,&old,&new);match case{"target-tree"=>wal["commit"]=g.put_tree(&g.tree(&c).unwrap()).unwrap().into(),"target-blob"=>wal["commit"]=g.put_blob(b"not a commit").unwrap().into(),"old"=>wal["changes"][0]["old"]["id"]=g.put_blob(b"forged").unwrap().into(),"ref"=>wal["ref"]="refs/heads/other".into(),"duplicate"=>{let a=wal["changes"].as_array_mut().unwrap();a.push(a[0].clone());},"id"=>wal["changes"][0]["new"]["id"]="--help".into(),_=>{}}journal::append(d.path(),"round",wal.clone()).unwrap();if case=="duplicate-begin"{journal::append(d.path(),"round",wal).unwrap();}let before=rows(d.path());let rf=refs(&g);let idx=fs::read(d.path().join(".git/index")).unwrap();assert!(merge::recover(d.path()).is_err(),"malformed case {case} was accepted");assert_eq!(rows(d.path()),before,"case {case}");assert_eq!(refs(&g),rf);assert_eq!(fs::read(d.path().join(".git/index")).unwrap(),idx);assert_eq!(fs::read(d.path().join("tracked")).unwrap(),b"base tracked\n");}}
#[test]fn valid_wal_crash_prefix_rolls_back_before_cas_and_finishes_after_cas(){for forward in [false,true]{let(d,g,base)=fixture();let(c,old,new)=target(&g,&base);journal::append(d.path(),"round",begin(&base,&c,&old,&new)).unwrap();util::replace_leaf(&d.path().join("tracked"),Some(&util::Leaf{mode:new.mode,bytes:g.blob(&new.id).unwrap()})).unwrap();if forward{g.advance("refs/heads/main",&c,Some(&base)).unwrap();}let index=fs::read(d.path().join(".git/index")).unwrap();assert_eq!(merge::recover(d.path()).unwrap()["recovered"],1);assert_eq!(fs::read(d.path().join("tracked")).unwrap(),if forward{b"new tracked\n".as_slice()}else{b"base tracked\n".as_slice()});assert_eq!(rows(d.path()).last().unwrap()["t"],if forward{"advance/end"}else{"advance/rollback"});assert_eq!(fs::read(d.path().join(".git/index")).unwrap(),index);assert_eq!(merge::recover(d.path()).unwrap()["recovered"],0);}}
#[test]fn drift_rejects_user_edits_deletions_and_symlink_parent_without_changing_index(){for shape in ["edit","delete","link"]{let(d,g,base)=fixture();let(c,_,_)=target(&g,&base);let idx=fs::read(d.path().join(".git/index")).unwrap();match shape{"edit"=>fs::write(d.path().join("tracked"),b"user work").unwrap(),"delete"=>fs::remove_file(d.path().join("tracked")).unwrap(),_=>{fs::remove_file(d.path().join("tracked")).unwrap();std::os::unix::fs::symlink("outside",d.path().join("tracked")).unwrap();}}let before=util::leaf(&d.path().join("tracked")).unwrap();assert!(merge::advance_verified(d.path(),"r1",&base,&c).is_err());assert_eq!(util::leaf(&d.path().join("tracked")).unwrap(),before);assert_eq!(g.resolve("refs/heads/main").unwrap().as_deref(),Some(base.as_str()));assert_eq!(fs::read(d.path().join(".git/index")).unwrap(),idx);assert!(!rows(d.path()).iter().any(|x|x["t"]=="advance/begin"));}}
#[test]fn file_symlink_replacements_are_atomic_and_failure_preserves_prior_leaf(){let d=tempfile::tempdir().unwrap();let p=d.path().join("leaf");let file=util::Leaf{mode:0o100755,bytes:b"executable".to_vec()};let link=util::Leaf{mode:0o120000,bytes:b"safe-relative-target".to_vec()};util::replace_leaf(&p,Some(&file)).unwrap();util::replace_leaf(&p,Some(&link)).unwrap();assert_eq!(util::leaf(&p).unwrap(),Some(link.clone()));let invalid=util::Leaf{mode:0o120000,bytes:b"bad\0target".to_vec()};assert!(util::replace_leaf(&p,Some(&invalid)).is_err());assert_eq!(util::leaf(&p).unwrap(),Some(link));util::replace_leaf(&p,Some(&file)).unwrap();assert_eq!(util::leaf(&p).unwrap(),Some(file.clone()));let invalid=util::Leaf{mode:0o600,bytes:b"unsupported".to_vec()};assert!(util::replace_leaf(&p,Some(&invalid)).is_err());assert_eq!(util::leaf(&p).unwrap(),Some(file));assert!(!fs::read_dir(d.path()).unwrap().any(|e|e.unwrap().file_name().to_string_lossy().starts_with(".tmp-leaf")));}
#[test]fn fold_operational_errors_are_not_reported_as_conflict(){let(d,g,base)=fixture();let _=d;assert!(merge::fold(&g,&base,&["1".repeat(40)]).is_err());}

#[test]fn actual_directory_write_failure_preserves_original_atomic_leaf(){use std::os::unix::fs::PermissionsExt;let d=tempfile::tempdir().unwrap();let p=d.path().join("leaf");let old=util::Leaf{mode:0o100644,bytes:b"old bytes".to_vec()};util::replace_leaf(&p,Some(&old)).unwrap();fs::set_permissions(d.path(),fs::Permissions::from_mode(0o500)).unwrap();let result=util::replace_leaf(&p,Some(&util::Leaf{mode:0o100644,bytes:b"new bytes".to_vec()}));fs::set_permissions(d.path(),fs::Permissions::from_mode(0o700)).unwrap();assert!(result.is_err(),"fixture must truly deny directory writes");assert_eq!(util::leaf(&p).unwrap(),Some(old));assert_eq!(fs::read_dir(d.path()).unwrap().count(),1);}
#[test]fn wal_recovery_refuses_post_crash_user_edit_and_preserves_pending_history(){let(d,g,base)=fixture();let(c,old,new)=target(&g,&base);journal::append(d.path(),"round",begin(&base,&c,&old,&new)).unwrap();fs::write(d.path().join("tracked"),b"new user edit after crash").unwrap();let before=rows(d.path());let idx=fs::read(d.path().join(".git/index")).unwrap();assert!(merge::recover(d.path()).is_err());assert_eq!(rows(d.path()),before);assert_eq!(fs::read(d.path().join("tracked")).unwrap(),b"new user edit after crash");assert_eq!(fs::read(d.path().join(".git/index")).unwrap(),idx);assert_eq!(g.resolve("refs/heads/main").unwrap().as_deref(),Some(base.as_str()));}
#[test]fn wal_recovery_rejects_unsafe_symlink_landing_like_normal_advance(){let(d,g,base)=fixture();let mut m=g.tree(&base).unwrap();let old=m["tracked"].clone();let new=Entry{kind:"symlink".into(),mode:0o120000,id:g.put_blob(b"/tmp/outside").unwrap()};m.insert("tracked".into(),new.clone());let c=g.commit_tree(&g.put_tree(&m).unwrap(),&[base.clone()],"unsafe link").unwrap();journal::append(d.path(),"round",begin(&base,&c,&old,&new)).unwrap();g.advance("refs/heads/main",&c,Some(&base)).unwrap();let before=rows(d.path());assert!(merge::recover(d.path()).is_err());assert_eq!(rows(d.path()),before);assert_eq!(fs::read(d.path().join("tracked")).unwrap(),b"base tracked\n");assert!(!fs::symlink_metadata(d.path().join("tracked")).unwrap().file_type().is_symlink());}
#[test]fn committed_stage_crash_finishes_from_durable_accept_and_landed_receipts(){let(d,g,base)=fixture();let p=round::command(d.path(),"new",&["goal".into()],&json!({"split":split(1)})).unwrap();let c=&p["contracts"][0];let w=c["agent"].as_str().unwrap();let mut v=View::load(d.path(),w,None).unwrap();v.write("result0",b"worker done\n",None).unwrap();let ck=v.checkpoint("worker").unwrap();journal::append(d.path(),w,json!({"t":"agent/stop","agent":w,"contract":c["id"],"reason":"end-turn","stopped":"done","steps":0})).unwrap();state(d.path(),"Working","Collecting");state(d.path(),"Collecting","Merging");let f=merge::fold(&g,&base,&[ck["commit"].as_str().unwrap().into()]).unwrap();let tree=f["tree"].as_str().unwrap();let target=g.commit_tree(tree,&[base.clone()],"fugue round r1").unwrap();journal::append(d.path(),"round",json!({"t":"merge/candidate","round":"r1","base":base,"tree":tree,"commit":target})).unwrap();state(d.path(),"Merging","Verifying");journal::append(d.path(),"round",json!({"t":"merge/accept","round":"r1","commit":target,"assertions":[{"assertion":"check0","verdict":"pass"}]})).unwrap();merge::advance_verified(d.path(),"r1",&base,&target).unwrap();state(d.path(),"Verifying","Committed");let z=round::command(d.path(),"work",&[],&json!({})).unwrap();assert_eq!(z["state"],"Rebuilding");assert_eq!(z["recovered"],true);assert_eq!(g.resolve("refs/heads/main").unwrap().as_deref(),Some(target.as_str()));assert_eq!(fs::read(d.path().join("result0")).unwrap(),b"worker done\n");}
#[test]fn verifying_resume_rejects_candidate_commit_tree_mismatch(){let(d,g,base)=fixture();let p=round::command(d.path(),"new",&["goal".into()],&json!({"split":split(1)})).unwrap();let c=&p["contracts"][0];let w=c["agent"].as_str().unwrap();let mut v=View::load(d.path(),w,None).unwrap();v.write("result0",b"worker done\n",None).unwrap();let ck=v.checkpoint("worker").unwrap();journal::append(d.path(),w,json!({"t":"agent/stop","agent":w,"contract":c["id"],"reason":"end-turn","stopped":"done","steps":0})).unwrap();state(d.path(),"Working","Collecting");state(d.path(),"Collecting","Merging");let empty=g.put_tree(&BTreeMap::new()).unwrap();journal::append(d.path(),"round",json!({"t":"merge/candidate","round":"r1","base":base,"tree":empty,"commit":ck["commit"]})).unwrap();state(d.path(),"Merging","Verifying");let before=rows(d.path());let rf=refs(&g);assert!(round::command(d.path(),"work",&[],&json!({"fail":"check0","retry":0})).is_err());assert_eq!(rows(d.path()),before);assert_eq!(refs(&g),rf);assert!(!d.path().join("result0").exists());}
